import type { GameManifestInput } from './manifest';
import type { CatalogStatus, SeedGame } from './seed-catalog';

// Ayvago Arcade: in-house retro games built on one shared runtime (selchook/ayvago-games) and
// served from one origin, each at ${ARCADE_ORIGIN}/games/<slug>/ with its ayvago.json, icon and
// cover beside it. Generated by scripts/gen-platform.mjs in that repository: regenerate there
// instead of editing by hand.

export const ARCADE_ORIGIN = 'https://ayvago-games-nine.vercel.app';

// 'coming_soon' until the origin is deployed and checked (docs/setup/phase-2.md, slice 2.6).
export const ARCADE_STATUS: CatalogStatus = 'live';

const ARCADE_ADDED_AT = '2026-10-27';

// Generous first limits: scores are only flagged during the calibration window.
const ARCADE_SCORING: GameManifestInput['scoring'] = {
  metric: 'points',
  order: 'desc',
  format: 'number',
  label: { en: 'Score', tr: 'Puan' },
  minDurationMs: 3000,
  maxPerSecond: 1000,
  maxScore: 10000000,
};

type ArcadeEntry = Pick<
  GameManifestInput,
  'title' | 'description' | 'category' | 'categories' | 'tags' | 'orientation' | 'input'
> &
  Partial<Pick<GameManifestInput, 'ageRating' | 'scoring' | 'version'>> & {
    slug: string;
    addedAt?: string;
    featured?: boolean;
    /** Online play: true = two-player rooms; a number = a table with that many seats (bots allowed). */
    multiplayer?: boolean | number;
  };

function arcadeGame({
  slug,
  addedAt,
  featured,
  multiplayer,
  ageRating,
  scoring,
  version,
  ...text
}: ArcadeEntry): SeedGame {
  return {
    slug,
    repo: 'selchook/ayvago-games',
    status: ARCADE_STATUS,
    addedAt: addedAt ?? ARCADE_ADDED_AT,
    ...(featured ? { featured } : {}),
    manifest: {
      id: slug.replace(/-/g, ''),
      ...text,
      entry: `${ARCADE_ORIGIN}/games/${slug}/`,
      players: { min: 1, max: typeof multiplayer === 'number' ? multiplayer : multiplayer ? 2 : 1 },
      scoring: scoring ?? ARCADE_SCORING,
      ads: { rewarded: [], interstitial: [] },
      ageRating: ageRating ?? '3+',
      sdkVersion: 2,
      assets: {
        icon: `/games/${slug}/ayvago/icon-512.png`,
        cover: `/games/${slug}/ayvago/cover-1920x1080.jpg`,
        screenshot: `/games/${slug}/ayvago/screenshot.jpg`,
        card: `/games/${slug}/ayvago/card-640x360.webp`,
        card2x: `/games/${slug}/ayvago/card-1280x720.webp`,
      },
      version: version ?? '1.0.0',
    },
  };
}

